'use strict';
/* TMT Dealer Intelligence — sample store operations, based on supplied VC PDF and HTML. */
const $=(q,root=document)=>root.querySelector(q), $$=(q,root=document)=>[...root.querySelectorAll(q)];
const ICONS={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',orbit:'<circle cx="12" cy="12" r="3"/><ellipse cx="12" cy="12" rx="10" ry="5" transform="rotate(-40 12 12)"/><path d="M9 2c5-1 10 4 11 9M4 14c1 5 6 8 10 8"/>',layers:'<path d="m3 7 9-5 9 5-9 5-9-5Zm0 5 9 5 9-5M3 17l9 5 9-5"/>',matrix:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M9 3v18M15 3v18M3 9h18M3 15h18"/>',bolt:'<path d="m13 2-9 12h7l-1 8L21 9h-8l1-7Z"/>',play:'<path d="m8 4 12 8-12 8V4Z"/>',expand:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/>',motion:'<path d="M3 7h10M3 12h15M3 17h10M17 5l4 2-4 2m4 6-4 2 4 2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',up:'<path d="M4 17 11 10l4 4 6-9m-6 0h6v6"/>',check:'<path d="m5 12 4 4L20 5"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 4a4 4 0 0 1 0 8m2 3a5 5 0 0 1 3 6"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7Z"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6M17 2v6M3 11h18m-12 4h3m3 0h3"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>'};
function icon(n){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${ICONS[n]||ICONS.spark}</svg>`;}
function hydrate(root=document){$$('[data-icon]',root).forEach(el=>el.innerHTML=icon(el.dataset.icon));}
const gold='#dbc19a',ice='#9ad7d4',dim='#596871',orange='#dd9b75';

function fmt(n,d){return n.toLocaleString('en-US',{minimumFractionDigits:d??(n%1?1:0),maximumFractionDigits:d??(n<1?2:1)})}

function signed(n,d=1){return `${n>=0?'+':'−'}${Math.abs(n).toFixed(d)}`}

function escapeHtml(v){return String(v).replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]))}

function tag(label,color=''){return `<span class="pill ${color}"><i></i>${label}</span>`}

function metric(label,value,unit,delta,compare,id,view){return `<button class="metric" data-${view?'view':'detail'}="${view||id}" aria-label="${label}の詳細"><div class="metric-head"><span>${label}</span>${icon('up')}</div><div class="metric-value"><span class="count-up" data-number="${value}">${fmt(value)}</span><small>${unit}</small></div><div class="metric-foot"><b>${delta}</b>${compare}</div><div class="metric-spark"><canvas id="spark-${id}" aria-hidden="true"></canvas></div></button>`}

function chartDefaults(){Chart.defaults.color='#7e8b93';Chart.defaults.font.family="'SFMono-Regular',Consolas,monospace";Chart.defaults.font.size=8;Chart.defaults.plugins.legend.display=false;Chart.defaults.plugins.tooltip.backgroundColor='#202729';Chart.defaults.plugins.tooltip.titleColor=gold;Chart.defaults.plugins.tooltip.bodyColor='#e7edeb';Chart.defaults.plugins.tooltip.borderColor='#dbc19a44';Chart.defaults.plugins.tooltip.borderWidth=1;Chart.defaults.plugins.tooltip.padding=12;Chart.defaults.animation.duration=state.motion?1000:0;}

function lineChart(id,labels,datasets,extra={}){const canvas=$('#'+id);if(!canvas)return;const ctx=canvas.getContext('2d');const fill=ctx.createLinearGradient(0,0,0,250);fill.addColorStop(0,'#dbc19a23');fill.addColorStop(1,'#dbc19a00');const c=new Chart(ctx,{type:'line',data:{labels,datasets:datasets.map((ds,i)=>({borderWidth:1.7,pointRadius:0,pointHoverRadius:4,tension:.38,fill:i===0,backgroundColor:fill,...ds}))},options:{responsive:true,maintainAspectRatio:false,animation:state.motion?{duration:1000,easing:'easeOutQuart'}:false,interaction:{mode:'index',intersect:false},plugins:{legend:{display:false},tooltip:{callbacks:{label:ctx=>`${ctx.dataset.label}: ${Number(ctx.parsed.y).toFixed(1)}%`}}},scales:{x:{grid:{display:false},border:{display:false},ticks:{maxTicksLimit:5,color:'#647078',font:{size:7},maxRotation:0}},y:{border:{display:false},grid:{color:'#ffffff07',drawTicks:false},ticks:{maxTicksLimit:4,padding:9,font:{size:7},callback:v=>v+'%'}}},...extra}});charts.push(c);return c}

function spark(id,data,color=gold){const el=$('#spark-'+id);if(!el)return;const c=new Chart(el,{type:'line',data:{labels:data.map((_,i)=>i),datasets:[{data,borderColor:color,borderWidth:1.2,pointRadius:0,tension:.4,fill:false}]},options:{responsive:true,maintainAspectRatio:false,animation:state.motion?{duration:1400}:false,events:[],plugins:{legend:{display:false},tooltip:{enabled:false}},scales:{x:{display:false},y:{display:false}}}});charts.push(c)}

function animateNumbers(){if(!state.motion)return;$$('.count-up').forEach(el=>{const target=+el.dataset.number;let start;let raf;const decimals=target%1?1:0;function draw(t){start??=t;const p=Math.min(1,(t-start)/1100),e=1-Math.pow(1-p,4);el.textContent=fmt(target*(.63+.37*e),decimals);if(p<1)raf=requestAnimationFrame(draw)}raf=requestAnimationFrame(draw);animationHandles.push(()=>cancelAnimationFrame(raf));})}

function openDrawer(html){previousFocus=document.activeElement;$('#drawerContent').innerHTML=html;$('#drawerBackdrop').hidden=false;$('#detailDrawer').hidden=false;document.body.style.overflow='hidden';$('.shell').inert=true;$('.sidebar').inert=true;$('#tourBar').inert=true;hydrate($('#detailDrawer'));$('#drawerClose').focus();if(state.tour)pauseTour(true)}

function closeDrawer(){if(drawerChart){drawerChart.destroy();drawerChart=null}$('#drawerBackdrop').hidden=true;$('#detailDrawer').hidden=true;document.body.style.overflow='';$('.shell').inert=false;$('.sidebar').inert=false;$('#tourBar').inert=false;if(previousFocus?.isConnected)previousFocus.focus()}

function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200)}

function toggleMotion(){state.motion=!state.motion;document.body.classList.toggle('motion-off',!state.motion);$('#motionButton').setAttribute('aria-label',state.motion?'アニメーションを停止':'アニメーションを再開');Chart.defaults.animation.duration=state.motion?1000:0;charts.forEach(c=>{c.options.animation=state.motion?{duration:800}:false;c.update('none')});toast(state.motion?'アニメーションを再開しました':'アニメーションを停止しました')}

function actionCard(a){return `<article class="action-card ${a.status==='done'?'done-card':''}"><div class="action-priority"><span>${escapeHtml(a.status==='done'?'COMPLETED':a.priority)}</span><span>${escapeHtml(a.group)}</span></div><h3>${escapeHtml(a.title)}</h3><p>${escapeHtml(a.description)}</p><div class="action-impact">↗ ${escapeHtml(a.impact)}</div><div class="action-meta"><span class="avatar">${escapeHtml(a.owner)}</span><span>${escapeHtml(a.ownerName)}</span><span>${escapeHtml(a.due)}</span></div><button class="action-move" data-move="${escapeHtml(a.id)}"><span>${a.status==='todo'?'取り組みを開始':a.status==='doing'?'完了にする':'もう一度取り組む'}</span>${icon(a.status==='doing'?'check':'arrow')}</button></article>`}

function makeNetwork(canvas,mode){if(!canvas)return;const ctx=canvas.getContext('2d');let width=1,height=1,raf,stopped=false,hover={x:0,y:0},last=0,phase=0;const points=Array.from({length:mode==='core'?220:154},(_,i)=>{const y=1-(i/(mode==='core'?219:153))*2,r=Math.sqrt(1-y*y),a=i*2.3999632297;return {x:Math.cos(a)*r,y,z:Math.sin(a)*r}});const links=[];for(let i=0;i<points.length;i++){for(let j=i+1;j<points.length;j++){const a=points[i],b=points[j],d=Math.hypot(a.x-b.x,a.y-b.y,a.z-b.z);if(d<.29)links.push([i,j])}}
function resize(){const r=canvas.getBoundingClientRect();width=r.width;height=r.height;const dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);draw(last||0)}
function draw(t){if(stopped)return;ctx.clearRect(0,0,width,height);const core=mode==='core',cx=width*.5,cy=height*(core?.54:.48),radius=Math.min(width*(core?.23:.27),height*(core?.29:.47));const angle=phase+hover.x*.1,tilt=.28+hover.y*.1;const cs=Math.cos(angle),sn=Math.sin(angle),ct=Math.cos(tilt),st=Math.sin(tilt);const projected=points.map(p=>{const x=p.x*cs+p.z*sn,z=p.z*cs-p.x*sn,y=p.y*ct-z*st,z2=p.y*st+z*ct;return {x:cx+x*radius*(core?1:1.42),y:cy+y*radius*.85,z:z2}});
const halo=ctx.createRadialGradient(cx,cy,5,cx,cy,radius*1.8);halo.addColorStop(0,core?'#c3a57613':'#9ad7d40e');halo.addColorStop(1,'#00000000');ctx.fillStyle=halo;ctx.fillRect(0,0,width,height);
ctx.strokeStyle='#dbc19a13';ctx.lineWidth=.65;for(let i=0;i<3;i++){ctx.beginPath();ctx.ellipse(cx,cy,radius*(1.13+i*.14)*(core?1:1.2),radius*(.35+i*.12),-.37+i*.67,0,Math.PI*2);ctx.stroke();}
for(const [i,j] of links){const a=projected[i],b=projected[j],alpha=(a.z+b.z+2)/4*.2+.025;ctx.strokeStyle=`rgba(${core?'219,193,154':'154,215,212'},${alpha})`;ctx.lineWidth=.6;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke()}
projected.forEach((p,i)=>{let alpha=(p.z+1)/2*.7+.09;ctx.fillStyle=`rgba(${i%6===0?'154,215,212':'219,193,154'},${alpha})`;ctx.beginPath();ctx.arc(p.x,p.y,p.z>.5?1.2:.75,0,Math.PI*2);ctx.fill();if(i%29===0&&p.z>.2){ctx.strokeStyle=`rgba(219,193,154,${alpha*.22})`;ctx.beginPath();ctx.arc(p.x,p.y,4+Math.sin(phase*3+i)*2,0,Math.PI*2);ctx.stroke();}});
if(core){const endPoints=[[.18,.43],[.23,.79],[.80,.36],[.81,.70]];endPoints.forEach(([x,y],i)=>{const ex=width*x,ey=height*y;ctx.beginPath();ctx.moveTo(cx,cy);ctx.quadraticCurveTo((cx+ex)/2,ey,ex,ey);ctx.setLineDash([2,5]);ctx.strokeStyle=i===['GS','BP','INS','ACC'].indexOf(state.domain)?'#dbc19a55':'#9ad7d42a';ctx.stroke();ctx.setLineDash([]);const p=(phase*.35+i*.26)%1;const px=(1-p)*(1-p)*cx+2*(1-p)*p*(cx+ex)/2+p*p*ex,py=(1-p)*(1-p)*cy+2*(1-p)*p*ey+p*p*ey;ctx.fillStyle=i%2?ice:gold;ctx.shadowColor=gold;ctx.shadowBlur=9;ctx.beginPath();ctx.arc(px,py,2,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;});const mask=ctx.createRadialGradient(cx,cy,0,cx,cy,radius*.65);mask.addColorStop(0,'#111719eb');mask.addColorStop(.6,'#111719b5');mask.addColorStop(1,'#11171900');ctx.fillStyle=mask;ctx.fillRect(cx-radius,cy-radius,radius*2,radius*2);}
}
function loop(t){if(stopped)return;if(!document.hidden&&t-last>32){if(state.motion)phase+=.0038;draw(t);last=t}raf=requestAnimationFrame(loop)}const onMove=e=>{const r=canvas.getBoundingClientRect();hover={x:(e.clientX-r.left)/r.width-.5,y:(e.clientY-r.top)/r.height-.5}};canvas.addEventListener('pointermove',onMove);const ro=new ResizeObserver(resize);ro.observe(canvas);resize();raf=requestAnimationFrame(loop);const cleanup=()=>{stopped=true;cancelAnimationFrame(raf);ro.disconnect();canvas.removeEventListener('pointermove',onMove)};animationHandles.push(cleanup);activeNetwork={draw};}
const VIEWS=['overview','matrix','drivers','network','vc','actions'];
const META={overview:['Monday Cockpit','THAILAND DEALER OPERATIONS / 01','A stronger Monday','先週の実績、今週の注意点、今日の一手を。'],matrix:['21 Core KPIs','5 BUSINESS AREAS / 21 CORE KPIs','Every signal matters','GS・BP・保険・用品・固定費。実数から、改善の余地を読む。'],drivers:['Growth Drivers','FROM CORE KPI TO PROCESS / 03','Find the next opportunity','タイヤ、バッテリー、作業枠。現場で変えられることから。'],network:['Dealer Network','THAILAND / 154 DEALERS','Grow stronger, together','同じ条件の店舗と比べて、次に伸ばす指標を見つける。'],vc:['VC Roadmap','VALUE CHAIN ABSORPTION / 05','Toward ninety. And beyond','アフターセールスで固定費を支える。70%から、長期90%へ。'],actions:['Action Studio','MONDAY BRIEFING / 06','Make the next move','今週の重点を、朝礼とチームの行動へ。']};
const GROUPS={GS:'一般整備',BP:'鈑金塗装',INS:'保険',ACC:'用品',COST:'固定費'};
const STORES={'BKK-001':{name:'Bangkok Central',region:'バンコク首都圏',factor:1,ratio:72,peer:76},'CNX-001':{name:'Chiang Mai North',region:'北部',factor:1.07,ratio:78,peer:77},'KKN-001':{name:'Khon Kaen East',region:'東北部',factor:.91,ratio:68,peer:73},'HKT-001':{name:'Phuket South',region:'南部',factor:1.03,ratio:75,peer:74},ALL:{name:'タイ全国 / 全154店',region:'全国',factor:.97,ratio:70,peer:76}};
const SOURCE_LABELS={existing:'既存KPI',system:'システム抽出',dealer:'販売店入力'};
const STATUS_LABELS={ideal:'理想水準',on:'基準付近',warn:'重点改善',missing:'入力確認待ち'};
const STORAGE_KEY='nexus-tmt-actions-v2';
let saved={};try{saved=JSON.parse(localStorage.getItem(STORAGE_KEY))||{}}catch{}
let state={view:'overview',store:'BKK-001',period:'2026-10-05',category:'ALL',status:'all',compare:'hq',layout:'compact',horizon:13,driver:'tire',domain:'GS',region:'ALL',size:'ALL',sort:'ratio',page:0,motion:!matchMedia('(prefers-reduced-motion: reduce)').matches,tires:8.4,bay:49,cost:0,year:2026,roadmap:'2026',actions:[],tour:false,tourPaused:false,tourStep:0,tourElapsed:0};
let charts=[],animationHandles=[],drawerChart=null,previousFocus=null,toastTimer,tourTimer,activeNetwork=null,chatTimers=[],tourAutoTimers=[];
function getActions(){const a=saved[state.store];return Array.isArray(a)&&a.length&&a.every(x=>x.id&&['todo','doing','done'].includes(x.status))?structuredClone(a):structuredClone(INITIAL_ACTIONS)}
state.actions=getActions();
function storeInfo(){return STORES[state.store]}
function periodFactor(){return state.period==='2026-09-28'?.96:state.period==='2026-09-21'?.93:1}
function factor(){return storeInfo().factor*periodFactor()}
function ratioBase(){return storeInfo().ratio+(state.period==='2026-09-28'?-3:state.period==='2026-09-21'?-4.5:0)}
function currentKpis(){return KPI_DATA.map(k=>{const f=1+(factor()-1)*(k.direction===1?.7:-.35),value=+(k.value*f).toFixed(k.precision);const progress=k.direction===1?value/k.target:k.target/value;let status=!k.ready?'missing':state.store==='BKK-001'&&state.period==='2026-10-05'?k.baseStatus:progress>=1.02?'ideal':progress>=.95?'on':'warn';return {...k,value,progress,status}})}
function benchmark(k){return state.compare==='peer'?parseFloat(k.peer):state.compare==='history'?parseFloat(k.history):k.target}
function compareName(){return {hq:'本部・基準',peer:'類似店平均',history:'13週平均'}[state.compare]}
function conditionLabel(){return `${storeInfo().name}${state.store==='ALL'?'':' / デモ店'} · ${state.period}週`}
function sampleNote(label='参考構成：提供資料 / 数値・店舗はデモ'){return `<p class="source-note">${label}</p>`}
function panelTitle(jp,en,right=''){return `<div class="section-heading"><h2>${jp}<small>${en}</small></h2>${right}</div>`}
function table(headers,rows,cls=''){return `<div class="table-scroll"><table class="tmt-table ${cls}"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function disposeView(){charts.forEach(c=>c.destroy());charts=[];animationHandles.forEach(fn=>fn());animationHandles=[];chatTimers.forEach(clearTimeout);chatTimers=[];activeNetwork=null}
function setView(name,options={}){if(!VIEWS.includes(name))name='overview';disposeView();state.view=name;const m=META[name];$('#breadcrumb').textContent=m[0];$('#pageEyebrow').textContent=m[1];$('#pageTitle').innerHTML=m[2]+'<span class="title-dot">.</span>';$('#pageSubtitle').textContent=m[3];$$('.nav-item').forEach(b=>{b.classList.toggle('active',b.dataset.view===name);b.setAttribute('aria-current',b.dataset.view===name?'page':'false')});if(location.hash!==`#${name}`)history.replaceState(null,'',`#${name}`);$('#viewRoot').innerHTML=`<section class="view" aria-label="${m[0]}">${({overview:renderOverview,matrix:renderMatrix,drivers:renderDrivers,network:renderNetwork,vc:renderVC,actions:renderActions})[name]()}</section>`;hydrate($('#viewRoot'));({overview:initOverview,matrix:initMatrix,drivers:initDrivers,network:initNetwork,vc:initVC,actions:initActions})[name]();animateNumbers();if(options.scroll!==false)window.scrollTo({top:0,behavior:'instant'})}
function renderOverview(){const revenue=+(12.8*factor()*(state.store==='ALL'?154:1)).toFixed(1),margin=+(31+(factor()-1)*8).toFixed(1),pending=state.actions.filter(a=>a.status!=='done').length;return `<div class="hero"><img class="hero-image" src="assets/vision.webp" alt="シャンパンゴールドの光をまとうコンセプトカー" fetchpriority="high"><div class="hero-content"><p class="eyebrow">TOYOTA THAILAND / DEALER PERFORMANCE</p><h2>店舗の未来を、<br><em>収益で動かす。</em></h2><p class="hero-description">タイヤ提案と、作業枠の使い切り。<br>今日の一手から、VC吸収率90%への道をつくる。</p><div class="hero-actions"><button class="gold-button" data-driver="tire">今週の重点を見る ${icon('arrow')}</button><button class="text-button" data-action="tour">${icon('play')} 60秒で全体を見る</button></div></div><div class="hero-label">154 DEALERS / ONE DIRECTION<span>VALUE CHAIN GROWTH</span></div><div class="hero-corner">MONDAY MORNING / THAILAND</div><div class="hero-caption"><i></i> CONCEPT VEHICLE</div></div>
<div class="manager-note"><span>${icon('spark')} 今週の店長メッセージ</span><p>入庫数は確保。次は、交換必要のお客様への見積提示と、空きワークベイの活用を徹底。</p><button class="text-button" data-view="actions">朝礼アクションへ →</button></div>
<div class="metric-grid">${metric('VC吸収率',ratioBase(),'%','目標 75%','固定費をVC収益でカバー','absorption','vc')}${metric('サービス売上',revenue,'MB','↗ 前週比 +4%','THB / 百万バーツ','sales','network')}${metric('サービス粗利率',margin,'%','目標 33%','売上に対する粗利','margin','vc')}${metric('未対応アクション',pending,'件','本日確認','未着手＋進行中','actions','actions')}</div>
<div class="domain-strip">${Object.entries(GROUPS).map(([g,n],i)=>`<button data-open-group="${g}"><span>${g}<small>${n}</small></span><b>${Math.round([68,81,74,92,55][i]*Math.min(1.05,factor()))}<small>%</small></b><i class="${[0,2,4].includes(i)?'warn':''}">${['注意','順調','注意','順調','要改善'][i]}</i></button>`).join('')}</div>
<div class="tmt-two"><article class="panel">${panelTitle('先週までの軌跡','VC ABSORPTION / TREND',`<div class="segmented"><button data-horizon="13" class="${state.horizon===13?'active':''}">13週</button><button data-horizon="52" class="${state.horizon===52?'active':''}">過去1年</button></div>`)}<div class="canvas-box"><canvas id="overviewChart" role="img" aria-label="VC吸収率と同規模店の推移"></canvas></div><div class="chart-key"><span><i></i>選択店 / 集計</span><span><i class="ice"></i>同規模平均</span><span>WEEKLY SAMPLE</span></div></article><article class="panel">${panelTitle('今週、見逃さないシグナル','PRIORITY ALERTS',tag('4 SIGNALS'))}<div class="signal-list">${[['gs-vc','高','タイヤ購入率','8.4% → Challenge 19.0%'],['gs-bay','高','ワークベイ稼働率','49% / 基準50%未達'],['ins-y35','中','保険更新率 Y3–5','46% / 13週平均49%'],['cost-people','中','人件費率','34% / 目安32%を超過']].map(([id,p,n,d])=>`<button class="signal-row text-button full-width" data-detail="${id}"><span class="priority-chip ${p==='高'?'high':''}">${p}</span><div style="text-align:left"><strong>${n}</strong><small>${d}</small></div><span>↗</span></button>`).join('')}</div></article></div>
<div class="tmt-two"><article class="panel">${panelTitle('タイヤ販売の、どこに余白があるか','THIS WEEK / TIRE FUNNEL',`<button class="text-button" data-driver="tire">深掘り →</button>`)}${compactFunnel()}<p class="note">交換必要82件に対し、見積提示54件。残る28件の説明と、当日作業枠の確保を優先。</p></article><article class="panel">${panelTitle('同じ規模の店舗から、学ぶ','STORE BENCHMARK',tag('PEER GROUP'))}${table(['指標','自店','同規模平均'],[['VC吸収率',ratioBase().toFixed(1)+'%',storeInfo().peer+'%'],['GS売上 / 人',(.69*factor()).toFixed(2)+' MB','0.72 MB'],['タイヤ購入率',(8.4*factor()).toFixed(1)+'%','12.1%'],['BP粗利率',(34*factor()).toFixed(1)+'%','32.0%']])}<p class="note">BP粗利率と、21 KPIの「BP貢献利益率」は区別して表示。</p></article></div><article class="panel monday-actions">${panelTitle('朝礼で伝える、4つのこと','MONDAY ACTIONS',`<button class="text-button" data-view="actions">チームの行動へ →</button>`)}<div class="brief-grid">${[['01','タイヤ点検 → 見積提示','SA全員の声かけ基準を統一','本日'],['02','水曜までの空きWB枠','即日交換できる枠を受付へ共有','水曜'],['03','保険の更新対象を割り付け','Y3–5の低下に対応','金曜'],['04','人件費と残業見込み','週後半の作業配分を調整','確認']].map(v=>`<div><span>${v[0]}</span><h3>${v[1]}</h3><p>${v[2]}</p><small>${v[3]}</small></div>`).join('')}</div></article>${sampleNote('Monday Store Manager Dashboardをタイ販売店向けに再構成。金額はTHBのサンプルに置換。')}`}
function compactFunnel(){return `<div class="compact-funnel">${[['点検実施',420,'来店顧客'],['交換必要',82,'判定率 19.5%'],['見積提示',54,'提示率 65.9%'],['成約',18,'成約率 33.3%']].map((v,i)=>`<button data-funnel="${i}"><span>0${i+1} / ${v[0]}</span><b>${v[1]}</b><small>${v[2]}</small></button>`).join('')}</div>`}
function initOverview(){const n=state.horizon,base=ratioBase(),labels=Array.from({length:n},(_,i)=>`W${i+1}`);const curve=labels.map((_,i)=>+(base-7.2+(i/(n-1))*7.2+Math.sin(i*.9)*.9).toFixed(1));curve[n-1]=base;lineChart('overviewChart',labels,[{label:'選択店',data:curve,borderColor:gold},{label:'同規模平均',data:labels.map((_,i)=>+(storeInfo().peer-3.5+i/(n-1)*3.5+Math.sin(i*.6)*.5).toFixed(1)),borderColor:ice,fill:false}]);['absorption','sales','margin','actions'].forEach((id,i)=>spark(id,[4,5,4.6,6,5.8,7,8,7.2,9,10],i%2?gold:ice));$$('[data-horizon]').forEach(b=>b.onclick=()=>{state.horizon=+b.dataset.horizon;setView('overview',{scroll:false})})}
function renderMatrix(){const list=currentKpis(),counts=['ideal','on','warn','missing'].map(s=>list.filter(k=>k.status===s).length);return `<div class="matrix-summary"><div><b>21</b><small>CORE KPIs</small></div>${counts.map((v,i)=>`<div><b style="color:${['var(--green)',gold,orange,'#88b6e4'][i]}">${String(v).padStart(2,'0')}</b><small>${['理想水準','基準付近','重点改善','入力確認待ち'][i]}</small></div>`).join('')}<div class="summary-note">実績・実数・改善余地を、<br><span>類似店 / 13週 / 本部</span>で比較。</div></div>
<div class="filter-toolbar"><div class="filter-tabs">${[['ALL','すべて'],...Object.entries(GROUPS).map(([k,v])=>[k,`${k} ${v}`])].map(([k,v])=>`<button data-category="${k}" class="${state.category===k?'active':''}">${v}</button>`).join('')}</div><div class="filter-right"><select id="compareFilter" class="filter-select" aria-label="比較対象">${[['hq','本部・基準'],['peer','類似店平均'],['history','13週平均']].map(([v,t])=>`<option value="${v}" ${state.compare===v?'selected':''}>${t}と比較</option>`).join('')}</select><select id="statusFilter" class="filter-select" aria-label="KPIの状態"><option value="all">すべての状態</option>${Object.entries(STATUS_LABELS).map(([v,t])=>`<option value="${v}" ${state.status===v?'selected':''}>${t}</option>`).join('')}</select><button class="ghost-button" id="matrixLayout">${state.layout==='compact'?'実数まで展開':'コンパクトに'}</button></div></div>
<div class="matrix-grid ${state.layout==='expanded'?'expanded':''}" id="matrixGrid">${renderKpiCards()}</div><div class="matrix-legend"><span class="status-dot ideal"><i></i>Ideal</span><span class="status-dot on"><i></i>Criterion付近</span><span class="status-dot warn"><i></i>Minimum / 要改善</span><span class="status-dot missing"><i></i>要入力・暫定値</span><span>カードを開いて、実数・改善余地・推移を確認</span></div>
<article class="panel readiness-panel">${panelTitle('測れる状態を、つくる','DATA READINESS / 19 OF 21',`<button class="text-button" data-info="sources">資料と設定の対応 →</button>`)}<div class="readiness-grid">${Object.entries(GROUPS).map(([g,n])=>{const a=list.filter(k=>k.group===g),ready=a.filter(k=>k.ready).length;return `<div><span>${g} <small>${n}</small><b>${ready} / ${a.length}</b></span><div class="bar-track"><div class="bar-fill" style="width:${ready/a.length*100}%"></div></div></div>`}).join('')}</div><div class="data-source-legend"><span class="source-badge existing">黄色 / 各部署が既に見ているKPI</span><span class="source-badge system">薄赤 / 社内システムから抽出</span><span class="source-badge dealer">青 / 販売店に入力を依頼</span></div><p class="note">作業種別構成とPHYDを入力確認待ちとしたデモ設定。表示する暫定値は例示、取得分類の個別割付もデモです。</p></article>`}
function renderKpiCards(){const a=currentKpis().filter(k=>(state.category==='ALL'||k.group===state.category)&&(state.status==='all'||k.status===state.status));return a.length?a.map(k=>{const compare=benchmark(k),diff=k.value-compare;return `<button class="kpi-card ${k.status}" data-detail="${k.id}"><div class="kpi-card-top"><span>${k.group} / ${String(k.i+1).padStart(2,'0')}</span><span class="status-dot ${k.status}"><i></i>${k.status==='missing'?'確認待ち':{ideal:'理想水準',on:'基準付近',warn:'要改善'}[k.status]}</span></div><h3>${k.name}</h3><div class="kpi-number">${fmt(k.value)}<small>${k.unit}${!k.ready?' 暫定':''}</small></div><div class="kpi-target"><span>${compareName()} ${Number.isFinite(compare)?fmt(compare)+k.unit:'未整備'}</span><b class="${k.status==='warn'?'warn':''}">${Number.isFinite(diff)?signed(diff,k.precision||1)+(k.unit==='%'?'pt':''):'—'}</b></div><div class="kpi-track"><span style="width:${Math.min(100,k.progress*85)}%"></span></div>${state.layout==='expanded'?`<div class="expanded-data"><p><span>実数</span>${k.actuals[0]}</p><p><span>改善余地</span>${k.actuals[1]}</p><div>類似店 ${k.peer} · 13週 ${k.history} · 本部 ${k.hq}</div><small class="source-badge ${k.sourceType}">${SOURCE_LABELS[k.sourceType]}</small></div>`:''}</button>`}).join(''):'<div class="empty-state">この条件に該当するKPIはありません。<br>領域や状態を変更してください。</div>'}
function initMatrix(){$$('[data-category]').forEach(b=>b.onclick=()=>{state.category=b.dataset.category;setView('matrix',{scroll:false})});$('#statusFilter').onchange=e=>{state.status=e.target.value;$('#matrixGrid').innerHTML=renderKpiCards()};$('#compareFilter').onchange=e=>{state.compare=e.target.value;$('#matrixGrid').innerHTML=renderKpiCards()};$('#matrixLayout').onclick=()=>{state.layout=state.layout==='compact'?'expanded':'compact';setView('matrix',{scroll:false})}}
const DRIVERS={tire:{label:'タイヤ',en:'TIRE PENETRATION',value:8.4,norm:8.4,target:8.5,challenge:19,counts:[420,82,54,18],title:'見積を出せなかった28件に、次の機会。',copy:'点検の結果を説明し、その日の作業枠をご案内。価格訴求の前に、提案漏れをなくす。',action:'交換必要のお客様へのタイヤ見積を徹底し、即日交換できるWB枠を受付と共有。'},battery:{label:'バッテリー',en:'BATTERY PENETRATION',value:5.2,norm:5.2,target:5.2,challenge:8,counts:[350,56,38,18],title:'診断結果を、交換の提案につなげる。',copy:'使用年数と診断結果を一緒に説明。次回まで待つリスクと交換の選択肢を、わかりやすく。',action:'バッテリー診断結果と交換目安をSA全員で統一し、要交換のお客様へ見積を提示。'},air:{label:'エアケア',en:'AIR CARE PENETRATION',value:6.9,norm:6.9,target:7,challenge:10,counts:[420,94,60,29],title:'車内の快適さを、点検の会話へ。',copy:'フィルターの状態とお客様の使い方を確認。見える説明で、提案から成約までをつなぐ。',action:'エアケアの点検結果を見える形で説明し、必要なお客様へ交換見積を提示。'}};
function renderDrivers(){return `<div class="driver-tabs filter-tabs">${[['tire','タイヤ'],['battery','バッテリー'],['air','エアケア'],['workbay','ワークベイ'],['bp','BP / T.CARE']].map(([k,n])=>`<button data-driver-tab="${k}" class="${state.driver===k?'active':''}">${n}</button>`).join('')}</div>${DRIVERS[state.driver]?renderProductDriver():state.driver==='workbay'?renderWorkbay():renderBP()}<article class="panel process-panel">${panelTitle('コアKPIから、行動のプロセスへ','CORE → DRIVER → PROCESS',tag('STEP BY STEP'))}<div class="process-line"><div><small>CORE KPI</small><strong>CRT / WB稼働 / 売上・人</strong><span>店舗の成果を把握する</span></div><b>→</b><div><small>DRIVER KPI</small><strong>入庫構成 / PM / 商品購入</strong><span>変化を生む要因を見つける</span></div><b>→</b><div><small>PROCESS KPI</small><strong>接触 → 提案 → 成約・来店</strong><span>現場の動作へ読み替える</span></div></div><details class="process-details"><summary>予約・入庫のプロセスツリーを開く <span>PDF p.7–8</span></summary><div class="process-tree"><div><h3>顧客基盤と入庫</h3><p>UIO / CPUS / CRT</p><small>車齢 Y1–5 / Y6–10 / Y11–15</small></div><div><h3>作業・サービス</h3><p>Periodic Maintenance<br>Other（予約あり / Walk-in）</p><small>Eco Pack / Additional Jobs / Tire</small></div><div><h3>継続・プラン</h3><p>TCFR+ / Smart Plan 3・5・10</p><small>Proposal / Success / Retention / Visit</small></div><div><h3>予約チャネル</h3><p>Call out / Call in / Online</p><small>Contact / Success / Receive</small></div></div><p class="note">最初は21コアKPIと重点商品の定着から。細かなプロセスは、必要な指標から段階的に展開。</p></details></article>`}
function renderProductDriver(){const d=DRIVERS[state.driver],gap=d.counts[1]-d.counts[2];return `<div class="driver-hero"><div><p class="eyebrow">GS / ${d.en}</p><h2>${d.title}</h2><p>${d.copy}</p></div><div class="driver-baseline"><small>PDF / CLASS AVERAGE</small><b>${d.value.toFixed(1)}<span>%</span></b><p>Norm ${d.norm}% / Criterion ${d.target}%</p></div></div><div class="tmt-two driver-main"><article class="panel">${panelTitle('点検から成約までを、つなぐ','SALES FUNNEL',tag(state.driver==='tire'?'HTML SAMPLE':'DEMO SAMPLE'))}<div class="funnel-canvas"><canvas id="driverFunnel" aria-label="点検、交換必要、見積、成約のファネル" role="img"></canvas></div><div class="funnel-statline"><span>見積未提示<b>${gap}<small>件</small></b></span><span>見積提示率<b>${(d.counts[2]/d.counts[1]*100).toFixed(1)}<small>%</small></b></span><span>見積 → 成約<b>${(d.counts[3]/d.counts[2]*100).toFixed(1)}<small>%</small></b></span></div><p class="note">購入率はPDFの平均値。ファネルは単店の別サンプルで、同じ集計母集団ではありません。</p></article><article class="panel">${panelTitle('提案を変えたら、何が動くか','OPPORTUNITY SIMULATOR',tag('WHAT IF'))}<p class="scenario-title">まず、<em>提案漏れをなくす。</em></p><div class="slider-row"><label for="proposalSlider">見積提示率<small>PROPOSAL RATE</small></label><input id="proposalSlider" type="range" min="50" max="100" value="${Math.round(d.counts[2]/d.counts[1]*100)}"><output id="proposalOutput"></output></div><div class="slider-row"><label for="closeSlider">見積からの成約率<small>SUCCESS RATE</small></label><input id="closeSlider" type="range" min="20" max="70" value="${Math.round(d.counts[3]/d.counts[2]*100)}"><output id="closeOutput"></output></div><div class="driver-sim-result"><div><small>成約の可能性</small><b id="possibleSales"></b></div><div><small>現在の成約から</small><b class="ice-text" id="extraSales"></b></div></div><button class="gold-button full-width" id="driverAction">${icon('bolt')} この改善を朝礼アクションへ</button><p class="note">交換必要件数 × 見積提示率 × 成約率の簡易試算。</p></article></div><div class="tmt-two"><article class="panel">${panelTitle('購入率と、生産性を一緒に上げる','GS / WAY OF THINKING')}${table(['指標','Current','Criterion','Challenge'],[['タイヤ購入率','8.4%','≥8.5%','≥19.0%'],['バッテリー購入率','5.2%','≥5.2%','段階改善'],['エアケア購入率','6.9%','≥7.0%','段階改善'],['GS売上 / 人 / 年','0.71 MB','≥0.70 MB','≥0.95 MB']])}<p class="note">PDF p.2。タイヤは販売プロセスを段階改善し、売上 / 人と連動して伸ばす。</p></article><article class="panel">${panelTitle('一台あたり売上の計画','BILL C / GS PURE & TIRE')}${table(['計画の区分','2026基準','2030 / 対2026'],[['GS Pure / タイヤ除く','100','109'],['GS Pure + Tire','100','122']])}<p class="note">PDF p.2の計画例。2030年は2026年比、GS Pure 109%、タイヤ込み122%。</p></article></div>`}
function renderWorkbay(){return `<div class="driver-hero"><div><p class="eyebrow">GS / WORKBAY UTILIZATION</p><h2>空いている時間を、店舗の収益へ。</h2><p>ワークベイ稼働率 ＝ 稼働した作業量 ÷ 最大能力。入庫予約、作業の配分、スタッフ配置を一緒に見る。</p></div><div class="driver-baseline"><small>CURRENT / SAMPLE STORE</small><b>49<span>%</span></b><p>稼働245h / 能力500h</p></div></div><div class="tmt-two"><article class="panel">${panelTitle('50%未達の店舗に、大きな余地','PDF NETWORK REFERENCE / 154 DEALERS')}<div class="wb-comparison"><div><strong>102</strong><span>店舗 / 50%未満</span><small>66% OF DEALERS</small></div><div><strong>52</strong><span>店舗 / 50%以上</span><small>34% OF DEALERS</small></div></div><div class="reference-levels"><div><small>NORM / PDF p.2</small><b>≥47%</b></div><div><small>CRITERION</small><b>≥50%</b></div><div><small>IDEAL EXAMPLE / p.5</small><b>55%</b></div></div><p class="note">PDF p.5の例ではDLR A 40%、B 47%、C 55%。高稼働店の予約と作業配分を比較する。</p></article><article class="panel">${panelTitle('今週、何時間を埋められるか','CAPACITY SIMULATOR')}<div class="slider-row"><label for="hoursSlider">追加の稼働時間<small>ADDITIONAL HOURS</small></label><input type="range" id="hoursSlider" min="0" max="100" step="5" value="5"><output id="hoursOutput">+5h</output></div><div class="driver-sim-result"><div><small>稼働率の試算</small><b id="bayPotential">50.0%</b></div><div><small>基準50%まで</small><b class="ice-text" id="bayGap">到達</b></div></div><button class="gold-button full-width" id="wbAction">${icon('bolt')} 作業枠の共有をアクションへ</button><p class="note">受付とワークショップで空き枠を共有。即日交換の案内を可能にする。</p></article></div>`}
function renderBP(){return `<div class="driver-hero"><div><p class="eyebrow">BP / BODY & PAINT</p><h2>T.CAREから、利益の質を変える。</h2><p>保険事業と連携してT.CARE CPU構成を高め、値引き負担と貢献利益率を見直す。</p></div><div class="driver-baseline"><small>CONTRIBUTION MARGIN</small><b>30<span>%</span></b><p>PDF Criterion &gt;35%</p></div></div><div class="tmt-two"><article class="panel">${panelTitle('BPが伸ばす、5つの指標','BP / WAY OF THINKING')}${table(['指標','Current','Norm','Criterion'],[['WB稼働率','80%','>80%','100%'],['技術員 / Active WB','87%','>90%','100%'],['CPU / UIO','24%','>25%','>30%'],['貢献利益率','30%','>30%','>35%'],['T.CARE CPU構成比','35%','>35%','>40%']])}<p class="note">PDF p.3。T.CARE CPU構成比のChallengeは50%超。コア21に別のKPIを足すのではなく、BPの改善ドライバーとして扱う。</p></article><article class="panel">${panelTitle('T.CAREの構成を変えてみる','T.CARE MIX / SAMPLE MODEL')}<div class="slider-row"><label for="tcareSlider">T.CARE CPU構成比<small>CURRENT 35%</small></label><input type="range" id="tcareSlider" min="35" max="60" value="35"><output id="tcareOutput">35%</output></div><div class="driver-sim-result"><div><small>貢献利益率の例</small><b id="bpPotential">30.0%</b></div><div><small>次の到達点</small><b class="ice-text">&gt;35%</b></div></div><button class="gold-button full-width" id="bpAction">${icon('bolt')} BPと保険の連携をアクションへ</button><p class="note">構成比1ptにつき貢献利益率0.25ptと置いた演出用の試算。実績との因果推定ではありません。</p></article></div><article class="panel">${panelTitle('値引きの構造を、見える形に','DISCOUNT STRUCTURE / PDF p.3')}${table(['顧客区分','T.CARE','Non T.CARE','Cash'],[['部品値引き','−15%','−20%以上','−5%'],['工賃値引き','−15%','−20%以上','−5%']])}<p class="note">保険・BPの顧客構成と値引き実績を照合し、利益への影響を現場で確認する。</p></article>`}
function initDrivers(){$$('[data-driver-tab]').forEach(b=>b.onclick=()=>{state.driver=b.dataset.driverTab;setView('drivers',{scroll:false})});if(DRIVERS[state.driver]){const d=DRIVERS[state.driver];const c=new Chart($('#driverFunnel'),{type:'bar',data:{labels:['点検実施','交換必要','見積提示','成約'],datasets:[{label:'件数',data:d.counts,backgroundColor:['#dbc19a42','#dbc19a70',gold,ice],borderRadius:4,barThickness:24}]},options:{indexAxis:'y',responsive:true,maintainAspectRatio:false,animation:state.motion?{duration:950}:false,plugins:{legend:{display:false}},scales:{x:{grid:{color:'#ffffff08'},border:{display:false},ticks:{font:{size:9}}},y:{grid:{display:false},border:{display:false},ticks:{font:{size:11},color:'#bec5c6'}}}}});charts.push(c);const update=()=>{const p=+$('#proposalSlider').value,q=+$('#closeSlider').value,n=Math.round(d.counts[1]*p/100*q/100);$('#proposalOutput').textContent=p+'%';$('#closeOutput').textContent=q+'%';$('#possibleSales').innerHTML=n+'<small>件</small>';$('#extraSales').innerHTML=signed(n-d.counts[3],0)+'<small>件</small>'};$('#proposalSlider').oninput=update;$('#closeSlider').oninput=update;update();$('#driverAction').onclick=()=>addAction({id:'driver-'+state.driver,title:d.label+'の提案漏れを、今週なくす。',description:d.action,group:'GS',impact:`見積提示率 ${$('#proposalSlider').value}% / 成約率 ${$('#closeSlider').value}% のデモ施策`})}else if(state.driver==='workbay'){const update=()=>{const h=+$('#hoursSlider').value;$('#hoursOutput').textContent='+'+h+'h';$('#bayPotential').textContent=((245+h)/500*100).toFixed(1)+'%';$('#bayGap').textContent=h>=5?'到達':'あと'+(5-h)+'h'};$('#hoursSlider').oninput=update;update();$('#wbAction').onclick=()=>addAction({id:'driver-workbay',title:'空き作業枠を、受付に共有する。',description:'水曜までの空きWB枠を共有し、タイヤ・バッテリーの即日交換を提案できる状態にする。',group:'GS',impact:`追加稼働 ${$('#hoursSlider').value}h のサンプル計画`})}else{const update=()=>{const v=+$('#tcareSlider').value;$('#tcareOutput').textContent=v+'%';$('#bpPotential').textContent=(30+(v-35)*.25).toFixed(1)+'%'};$('#tcareSlider').oninput=update;$('#bpAction').onclick=()=>addAction({id:'driver-bp',title:'T.CAREの提案と値引きを、BP・保険で見直す。',description:'保険チームと鈑金塗装チームが一緒に顧客構成と値引き状況を確認。次の提案内容を揃える。',group:'BP',impact:`T.CARE CPU構成比 ${$('#tcareSlider').value}% を検討`})}}
const REGIONS=['バンコク首都圏','中部','北部','東北部','南部'];
const DEALERS=Array.from({length:154},(_,i)=>{const region=REGIONS[i%5],size=['大規模','中規模','小規模'][i%3];return {id:'TH-'+String(i+1).padStart(3,'0'),name:['Bangkok','Ayutthaya','Chiang Mai','Khon Kaen','Phuket'][i%5]+' '+String(Math.floor(i/5)+1).padStart(2,'0'),region,size,ratio:+(58+(i*17%330)/10).toFixed(1),wb:i<102?+(35+(i*13%145)/10).toFixed(1):+(50+(i*11%220)/10).toFixed(1),tire:+(5+(i*7%145)/10).toFixed(1),margin:+(25+(i*9%130)/10).toFixed(1),ready:17+i%5}});
Object.entries(STORES).filter(([id])=>id!=='ALL').forEach(([id,s],i)=>Object.assign(DEALERS[i],{id,name:s.name,region:s.region,ratio:s.ratio,wb:[49,54,44,48][i],tire:+(8.4*s.factor).toFixed(1)}));
function networkRows(){let a=DEALERS.filter(d=>(state.region==='ALL'||d.region===state.region)&&(state.size==='ALL'||d.size===state.size));return a.sort((a,b)=>state.sort==='name'?a.name.localeCompare(b.name):b[state.sort]-a[state.sort])}
function renderNetwork(){const rows=networkRows(),mean=rows.length?rows.reduce((s,d)=>s+d.ratio,0)/rows.length:0;return `<div class="network-top"><article class="panel network-hero-panel">${panelTitle('店舗の成長が、タイ全体の力になる','THAILAND DEALER NETWORK',tag('154 / DEMO'))}<div class="network-preview large-network"><canvas id="networkPreview" class="network-canvas" aria-label="154店舗を表すネットワーク" role="img"></canvas><div class="network-over-label">GS · BP · INSURANCE · ACCESSORIES · COST</div><div class="network-overlay"><div>154<small>DEALERS</small></div><div>05<small>BUSINESS AREAS</small></div><div>21<small>CORE KPIs</small></div></div></article><article class="panel">${panelTitle('規模と地域をそろえて、比較する','LIKE-FOR-LIKE COMPARISON')}<div class="reference-levels"><div><small>対象店</small><b>${rows.length}</b></div><div><small>平均VC吸収率</small><b>${mean.toFixed(1)}%</b></div><div><small>全国の出発点 / PDF</small><b>70%</b></div></div><p class="note">同規模・同地域の店舗と、上位 / 中位 / 下位のグループを比較。高い店舗の予約導線、提案習慣、スタッフ配置を現場で確認。</p><div class="network-insight">${icon('spark')}<span>数値の差を、接客・ホスピタリティ・作業動線の仮説へ。</span></div></article></div><div class="filter-toolbar"><div class="filter-tabs">${['ALL',...REGIONS].map(r=>`<button data-region="${r}" class="${state.region===r?'active':''}">${r==='ALL'?'全国':r}</button>`).join('')}</div><select class="filter-select" id="sizeFilter" aria-label="店舗規模">${['ALL','大規模','中規模','小規模'].map(v=>`<option value="${v}" ${state.size===v?'selected':''}>${v==='ALL'?'すべての規模':v}</option>`).join('')}</select></div><div class="tmt-two"><article class="panel">${panelTitle('稼働と収益の、位置関係','WORKBAY × ABSORPTION',tag('CLICK A DEALER'))}<div class="canvas-box network-chart"><canvas id="dealerScatter" role="img" aria-label="154店舗のワークベイ稼働率とVC吸収率"></canvas></div></article><article class="panel">${panelTitle('上位店から、次の一手を学ぶ','SEGMENT / PRIORITY THEMES')}${table(['グループ','優先する確認','現場で聞くこと'],[['上位 / ≥80%','良い習慣の再現','予約枠・提案の標準化'],['中位 / 70–80%','タイヤ・バッテリー','見積提示の漏れ'],['下位 / <70%','WB稼働と固定費','入庫計画・人員配置']])}<p class="note">グループ分けはデモ用設定。順位だけで判断せず、店舗属性と定性の確認を組み合わせる。</p></article></div><article class="panel">${panelTitle('ディーラー・ベンチマーク','154 SYNTHETIC DEALER RECORDS',`<select class="filter-select" id="sortDealer" aria-label="店舗並び順">${[['ratio','VC吸収率順'],['wb','WB稼働率順'],['tire','タイヤ購入率順'],['name','店舗名順']].map(([v,n])=>`<option value="${v}" ${state.sort===v?'selected':''}>${n}</option>`).join('')}</select>`)}<div id="dealerTable">${renderDealerTable()}</div></article>`}
function renderDealerTable(){const rows=networkRows(),pages=Math.max(1,Math.ceil(rows.length/8));state.page=Math.min(state.page,pages-1);const slice=rows.slice(state.page*8,state.page*8+8);return table(['店舗 / 架空','地域・規模','VC吸収率','WB稼働率','タイヤ購入率','取得KPI',''],slice.map(d=>[`${d.name}<small class="table-sub">${d.id}</small>`,`${d.region}<small class="table-sub">${d.size}</small>`,`${d.ratio.toFixed(1)}%`,`${d.wb.toFixed(1)}%`,`${d.tire.toFixed(1)}%`,`${d.ready}/21`,`<button class="text-button" data-dealer="${d.id}" aria-label="${d.name}の詳細">詳細 ↗</button>`]))+`<div class="pagination"><span>${rows.length?state.page*8+1:0}–${Math.min(rows.length,(state.page+1)*8)} / ${rows.length} 店</span><div><button id="pagePrev" class="ghost-button" ${state.page===0?'disabled':''}>← 前へ</button><button id="pageNext" class="ghost-button" ${state.page>=pages-1?'disabled':''}>次へ →</button></div></div>`}
function initNetwork(){makeNetwork($('#networkPreview'),'preview');const rows=networkRows();const c=new Chart($('#dealerScatter'),{type:'scatter',data:{datasets:[{label:'販売店',data:rows.map(d=>({x:d.wb,y:d.ratio,id:d.id,name:d.name})),pointRadius:4,pointHoverRadius:7,backgroundColor:rows.map(d=>d.ratio>=80?ice:d.ratio>=70?gold:'#dd9b7588')}]},options:{responsive:true,maintainAspectRatio:false,animation:state.motion?{duration:750}:false,onClick:(e,els)=>{if(els.length)openDealer(rows[els[0].index].id)},plugins:{tooltip:{callbacks:{label:ctx=>`${ctx.raw.name}: WB ${ctx.raw.x}% / VC ${ctx.raw.y}%`}}},scales:{x:{min:30,max:80,title:{display:true,text:'WB稼働率 (%)',font:{size:9}},grid:{color:'#ffffff08'},border:{display:false}},y:{min:50,max:100,title:{display:true,text:'VC吸収率 (%)',font:{size:9}},grid:{color:'#ffffff08'},border:{display:false}}}}});charts.push(c);$$('[data-region]').forEach(b=>b.onclick=()=>{state.region=b.dataset.region;state.page=0;setView('network',{scroll:false})});$('#sizeFilter').onchange=e=>{state.size=e.target.value;state.page=0;setView('network',{scroll:false})};$('#sortDealer').onchange=e=>{state.sort=e.target.value;state.page=0;refreshDealerTable()};bindPagination()}
function refreshDealerTable(){$('#dealerTable').innerHTML=renderDealerTable();bindPagination()}
function bindPagination(){$('#pagePrev').onclick=()=>{state.page--;refreshDealerTable()};$('#pageNext').onclick=()=>{state.page++;refreshDealerTable()}}
function openDealer(id){const d=DEALERS.find(d=>d.id===id);if(!d)return;openDrawer(`<p class="eyebrow">DEALER BENCHMARK / SAMPLE</p><h2>${d.name}</h2><p class="drawer-subtitle">${d.id} · ${d.region} · ${d.size}<br>比較体験のための架空ディーラーです。</p><div class="drawer-big">${d.ratio.toFixed(1)}<small>%</small></div><p class="note">VC吸収率</p><div class="drawer-comparison"><span>WB稼働率 <b>${d.wb}%</b></span><span>タイヤ購入率 <b>${d.tire}%</b></span></div><div class="drawer-section"><h3>WHAT TO LEARN</h3><div class="drawer-callout">${d.ratio>=80?'予約枠と当日作業枠をどう使い分けているか。高い店舗の習慣をチームで確認。':d.wb<50?'入庫の誘導と空きWB枠の共有を優先。タイヤ・バッテリーの即日交換につなぐ。':'見積提示率と成約率を確認。点検から提案までの取りこぼしを減らす。'}</div></div><button class="gold-button full-width" id="dealerDrivers">改善ドライバーを見る →</button>`);$('#dealerDrivers').onclick=()=>{closeDrawer();state.driver=d.wb<50?'workbay':'tire';setView('drivers')}}
function renderVC(){return `<div class="roadmap-milestones">${[['現在','70','2026年5月 / 全国参考'],['2026年末','72','Phase 1 / 21 KPI'],['2027年','81','GS・BP・INS＋改善'],['2030年','約90','固定費改善・用品を含む']].map((v,i)=>`<div><span>${v[0]}</span><b>${v[1]}<small>%</small></b><p>${v[2]}</p>${i<3?'<i>→</i>':''}</div>`).join('')}</div><div class="vc-top"><article class="panel absorption-panel">${panelTitle('VC収益で、固定費をどこまで支えるか','ABSORPTION RATIO',tag('SELECTED STORE'))}<div class="gauge-wrap"><canvas id="gaugeChart" role="img" aria-label="VC吸収率のシミュレーション"></canvas><div class="gauge-center"><b id="ratioValue">${ratioBase()}</b><span>%</span><small id="ratioLabel">CURRENT PERFORMANCE</small></div></div><div class="gauge-comparison"><span>選択店<b>${ratioBase().toFixed(1)}%</b></span><span>長期参考<b>90.0%</b></span><span>固定費を全額カバー<b>100.0%</b></span></div><div class="ratio-formula">VCの貢献利益 ÷ 固定費 × 100</div></article><article class="panel scenario-panel"><div class="scenario-topline"><p class="eyebrow">WHAT IF / DEALER GROWTH</p><button class="text-button" id="resetScenario">RESET ↺</button></div><h2 class="scenario-title">動かすのは、<em>現場のレバー。</em></h2><p class="note">GSの生産性と固定費改善を、吸収率の変化で体感。</p>${[['tire','タイヤ購入率','TIRE / CURRENT 8.4%',8.4,19,.1,state.tires],['bay','WB稼働率','WORKBAY / CURRENT 49%',49,80,1,state.bay],['cost','固定費の改善','COST OPTIMIZATION',0,15,.5,state.cost]].map(([key,j,en,min,max,step,value])=>`<div class="slider-row"><label for="${key}Slider">${j}<small>${en}</small></label><input id="${key}Slider" type="range" min="${min}" max="${max}" step="${step}" value="${value}"><output id="${key}Output">${value}%</output></div>`).join('')}<div class="scenario-result"><div><small>シナリオによる改善幅</small><b id="scenarioGain"></b></div><button class="ghost-button" id="applyScenario">実行の検討へ ${icon('arrow')}</button></div></article></div>
<div class="vc-bottom"><article class="panel">${panelTitle('2030年へ、段階的に積み上げる','ILLUSTRATIVE GROWTH PATH',tag('2026 → 2030'))}<div class="canvas-box" style="height:218px"><canvas id="projectionChart" role="img" aria-label="VC吸収率の改善シナリオ"></canvas></div><div class="chart-key"><span><i></i>改善シナリオ</span><span><i class="dim"></i>現在の延長</span><span>SIMULATION</span></div><div class="vc-timeline"><label for="yearSlider">HORIZON</label><input id="yearSlider" type="range" min="2026" max="2030" step="1" value="${state.year}"><output id="yearOutput">${state.year}</output></div><p class="note">選択店を起点とする演出用モデル。上段のPDF年度計画とは別の試算。</p></article><article class="panel">${panelTitle('既存事業の基準達成と、固定費改善','PDF / CONTRIBUTION LOGIC')}${table(['段階','収益・改善の内訳','吸収率'],[['現在','GS 44 + BP 20 + INS 6','70%'],['全店基準達成','GS 50 + BP 25 + INS 10','85%'],['2027計画','GS 46 + BP 24 + INS 6<br>＋固定費改善3 ＋用品2','81%'],['2030計画','基盤82 ＋固定費改善6 ＋用品2','90%']])}<p class="note">寄与の数値はpt。85%は固定費削減を除く基準達成ケースで、年度計画とは異なる比較軸。</p></article></div><div class="tmt-two"><article class="panel">${panelTitle('まず、5事業・21 KPIを定着させる','PHASE 1 / START OCT 2026')}<div class="phase-tags">${Object.entries(GROUPS).map(([g,j])=>`<span>${g}<small>${j}</small></span>`).join('')}</div><ol class="operating-steps"><li>参加販売店でモニタリングを開始</li><li>RA / ROと店舗別の改善計画を確認</li><li>週次で追跡し、変化と活動を評価</li><li>上位店の良い習慣を、他店舗へ展開</li></ol></article><article class="panel">${panelTitle('次の事業は、別枠で育てる','PHASE 2 / UNDER DEVELOPMENT')}<div class="future-business"><span>USED CAR<small>中古車事業</small></span><span>FIXFIT<small>追加事業</small></span></div><p class="note">PDFでは2026年内に追加事業の開発を進める構想。現行21 KPIの定着と並行して検討。</p><div class="phase-potential"><small>PDF REFERENCE / FUTURE POTENTIAL</small><strong>92.2% <span>+ α</span></strong></div></article></div>${sampleNote('VC資料.pdf p.1・6を優先。2030年は本文89%と図表90%を「約90%」に統一して表示。')}`}
function projectedRatio(year=state.year){const base=ratioBase(),path=(year-2026)/4*(90-base),gain=(state.tires-8.4)*.64+(state.bay-49)*.25+state.cost*.65;return Math.min(115,base+path+gain)}
function initVC(){const g=new Chart($('#gaugeChart'),{type:'doughnut',data:{datasets:[{data:[ratioBase(),100-ratioBase()],backgroundColor:[gold,'#ffffff08'],borderWidth:0,borderRadius:3,spacing:2,weight:1},{data:[90,10],backgroundColor:['#9ad7d450','#ffffff03'],borderWidth:0,weight:.13}]},options:{responsive:true,maintainAspectRatio:false,cutout:'86%',rotation:220,circumference:280,events:[],plugins:{tooltip:{enabled:false}},animation:state.motion?{duration:1100}:false,layout:{padding:8}}});charts.push(g);lineChart('projectionChart',['2026','2027','2028','2029','2030'],[{label:'改善シナリオ',data:[2026,2027,2028,2029,2030].map(y=>projectedRatio(y)),borderColor:gold},{label:'現在の延長',data:[0,1,2,3,4].map(i=>ratioBase()+i*1.7),borderColor:dim,borderDash:[4,4],fill:false}],{scales:{x:{border:{display:false},grid:{display:false},ticks:{font:{size:9}}},y:{min:50,max:120,border:{display:false},grid:{color:'#ffffff08'},ticks:{callback:v=>v+'%',font:{size:8}}}}});['tire','bay','cost'].forEach(key=>$('#'+key+'Slider').oninput=e=>{state[key==='tire'?'tires':key]=+e.target.value;updateScenario()});$('#yearSlider').oninput=e=>{state.year=+e.target.value;updateScenario()};$('#resetScenario').onclick=()=>{Object.assign(state,{tires:8.4,bay:49,cost:0,year:2026});setView('vc',{scroll:false})};$('#applyScenario').onclick=()=>{if(projectedRatio()-ratioBase()<.1){toast('スライダーを動かして改善シナリオをつくってください');return}addAction({id:'vc-scenario',group:'VC',title:'収益シナリオを、店舗の実行計画へ。',description:`タイヤ購入率${state.tires.toFixed(1)}%、WB稼働率${state.bay}%、固定費改善${state.cost.toFixed(1)}%。取り組む順序と担当を朝礼で確認。`,impact:`${state.year}年 / VC吸収率 ${projectedRatio().toFixed(1)}% のデモ試算`})};updateScenario()}
function updateScenario(){const r=projectedRatio();$('#ratioValue').textContent=r.toFixed(1);$('#ratioValue').style.color=r>=90?ice:'';$('#ratioLabel').textContent=r>ratioBase()?'SIMULATED POTENTIAL':'CURRENT PERFORMANCE';$('#tireOutput').textContent=state.tires.toFixed(1)+'%';$('#bayOutput').textContent=state.bay+'%';$('#costOutput').textContent=state.cost.toFixed(1)+'%';$('#scenarioGain').innerHTML='+'+(r-ratioBase()).toFixed(1)+'<span>pt</span>';$('#yearOutput').textContent=state.year;const g=charts[0];g.data.datasets[0].data=[Math.min(100,r),Math.max(0,100-r)];g.data.datasets[0].backgroundColor=[r>=90?ice:gold,'#ffffff08'];g.update('none');const p=charts[1];p.data.datasets[0].data=[2026,2027,2028,2029,2030].map(y=>projectedRatio(y));p.data.datasets[0].pointRadius=p.data.labels.map(y=>+y===state.year?4:0);p.update('none')}
function renderActions(){const done=state.actions.filter(a=>a.status==='done').length,total=state.actions.length;return `<div class="actions-banner"><div><p class="eyebrow">MONDAY BRIEFING / ${storeInfo().name.toUpperCase()}</p><h2>月曜の5分が、<br>店舗を変える。</h2><p>タイヤ提案、空きWB枠、保険更新、人件費。<br>今日の朝礼から、今週の担当と期限を揃える。</p></div><div class="action-progress"><div><b>${String(done).padStart(2,'0')}</b><span>/ ${String(total).padStart(2,'0')}</span></div><small>ACTIONS COMPLETED</small><div class="bar-track"><div class="bar-fill" style="width:${done/total*100}%"></div></div></div></div><div class="action-columns">${[['todo','次に動かす',gold],['doing','取り組んでいる',ice],['done','動かした','#99c8a8']].map(([s,n,c])=>`<section class="kanban-column"><div class="kanban-heading"><i style="background:${c}"></i>${n}<b>${state.actions.filter(a=>a.status===s).length}</b></div>${state.actions.filter(a=>a.status===s).map(actionCard).join('')||'<div class="kanban-empty"><span>✓</span>チームの一手を、ここへ。</div>'}</section>`).join('')}</div><div class="action-foot"><span class="local-note">店舗別に、このブラウザに保存。担当者への通知や実店舗への送信は行いません。</span><button class="text-button" id="resetActions">この店舗をデモ初期状態に戻す ↺</button></div>`}
function saveActions(){saved[state.store]=structuredClone(state.actions);try{localStorage.setItem(STORAGE_KEY,JSON.stringify(saved))}catch{toast('このブラウザでは保存できません。表示中のみ保持されます。')}}
function addAction(a){const id=String(a.id);const found=state.actions.find(x=>x.id===id);if(found){Object.assign(found,a);found.status='todo'}else state.actions.unshift({...a,priority:'KPI OPPORTUNITY',owner:'SM',ownerName:'店長・担当チーム',due:'次の朝礼',status:'todo'});saveActions();closeDrawer();setView('actions');toast('朝礼アクションに追加しました')}
function initActions(){$$('[data-move]').forEach(b=>b.onclick=()=>{const a=state.actions.find(x=>x.id===b.dataset.move);a.status={todo:'doing',doing:'done',done:'todo'}[a.status];saveActions();setView('actions',{scroll:false});toast({doing:'取り組みを開始しました',done:'アクションを完了しました',todo:'次に動かすリストへ戻しました'}[a.status])});$('#resetActions').onclick=()=>{state.actions=structuredClone(INITIAL_ACTIONS);saveActions();setView('actions',{scroll:false});toast('この店舗のデモ状態に戻しました')}}
function openKpi(id){const k=currentKpis().find(x=>x.id===id);if(!k)return;const comparison=benchmark(k);openDrawer(`<p class="eyebrow">21 CORE KPIs / ${k.group}</p><h2>${k.name}</h2><p class="drawer-subtitle">${conditionLabel()}<br>${k.headline}</p><div class="drawer-big">${fmt(k.value)}<small>${k.unit}${!k.ready?' / 暫定':''}</small></div><div class="drawer-comparison"><span>${compareName()} <b>${Number.isFinite(comparison)?fmt(comparison)+k.unit:'未整備'}</b></span><span>差分 <b>${Number.isFinite(comparison)?signed(k.value-comparison,k.precision||1)+(k.unit==='%'?'pt':''):'—'}</b></span></div><div class="detail-evidence"><div><span>実数 / 基準サンプル</span><strong>${k.actuals[0]}</strong></div><div><span>改善余地 / 基準サンプル</span><strong>${k.actuals[1]}</strong></div></div><div class="detail-benchmarks"><span>類似店<b>${k.peer}</b></span><span>13週平均<b>${k.history}</b></span><span>本部・基準<b>${k.hq}</b></span></div><div class="drawer-section"><h3>PERFORMANCE / 13 WEEKS</h3><div class="canvas-box" style="height:163px"><canvas id="detailChart" aria-label="13週間のKPI推移" role="img"></canvas></div><p class="note">前年差サンプル：${signed(k.yoy,k.precision||1)}${k.unit==='%'?'pt':k.unit}。実数・比較値はHTML基準例、推移・選択店舗の値はデモ生成。</p></div><div class="detail-levels"><span>Minimum<b>${fmt(k.min)}${k.unit}</b></span><span>Criterion<b>${fmt(k.target)}${k.unit}</b></span><span>Ideal<b>${fmt(k.ideal)}${k.unit}</b></span></div><p class="note">段階表示の閾値はデモ設定。PDFに値があるものは参考値を下記に併記。</p>${k.pdf?`<div class="drawer-callout reference-callout">${k.pdf}</div>`:''}<div class="drawer-section"><h3>DATA READINESS</h3><span class="source-badge ${k.sourceType}">${SOURCE_LABELS[k.sourceType]}</span><p>${k.ready?'集計済みを想定。': '販売店で確認・入力が必要。表示値は暫定サンプル。'}取得分類の個別割付はデモ設定です。</p></div><div class="drawer-section"><h3>NEXT BEST ACTION</h3><div class="drawer-callout">${k.action}</div></div><div class="drawer-actions"><button class="gold-button" id="addKpiAction">${icon('bolt')} アクションに追加</button><button class="ghost-button" id="detailDrill">${k.group==='GS'||k.group==='BP'?'ドライバーを深掘り':'VCへの影響を見る'}</button></div>`);const data=Array.from({length:13},(_,i)=>+(k.value*(.9+i*.008+Math.sin(i*1.2)*.018)).toFixed(Math.max(k.precision,1)));data[12]=k.value;drawerChart=new Chart($('#detailChart'),{type:'line',data:{labels:Array.from({length:13},(_,i)=>`W${i+1}`),datasets:[{label:k.name,data,borderColor:gold,borderWidth:1.8,pointRadius:0,pointHoverRadius:4,tension:.35,fill:true,backgroundColor:'#dbc19a10'},{label:'本部・基準',data:Array(13).fill(k.target),borderColor:ice,borderDash:[3,4],pointRadius:0,borderWidth:1}]},options:{responsive:true,maintainAspectRatio:false,animation:state.motion?{duration:700}:false,interaction:{mode:'index',intersect:false},scales:{x:{grid:{display:false},ticks:{maxTicksLimit:4,font:{size:9}},border:{display:false}},y:{grid:{color:'#ffffff08'},ticks:{maxTicksLimit:4,font:{size:9}},border:{display:false}}}}});$('#addKpiAction').onclick=()=>addAction({id:'kpi-'+k.id,group:k.group,title:k.headline+'。',description:k.action,impact:`${k.name} ${fmt(k.value)}${k.unit} → 目安 ${fmt(k.target)}${k.unit}`});$('#detailDrill').onclick=()=>{closeDrawer();state.driver=k.group==='BP'?'bp':k.id==='gs-bay'?'workbay':'tire';setView(['GS','BP'].includes(k.group)?'drivers':'vc')}}
function openSourceNotes(){openDrawer(`<p class="eyebrow">SOURCE & DEMO SETTINGS</p><h2>資料の構造を、画面へ。</h2><div class="guide-list"><div><b>01</b><span><strong>Monday Store Manager Dashboard.html</strong>店長メッセージ、VC吸収率、サービス売上・粗利率、未対応アクション、5領域サマリー、アラート、類似店比較、タイヤの4段階ファネル、4つの朝礼アクション。</span></div><div><b>02</b><span><strong>21コアKPIマトリクス サンプル.html</strong>5事業・21 KPIの名称、表示値、比較値、実数と改善余地を反映。GS 5 / BP 6 / 保険 6 / 用品 1 / 固定費 3。</span></div><div><b>03</b><span><strong>VC資料.pdf</strong>70 → 72 → 81 → 約90%の道筋、85%の基準達成ケース、GS・BPのガイドライン、T.CAREと値引き、WB低稼働店舗、段階導入、中古車・FIXFIT、プロセスツリー。</span></div><div><b>04</b><span><strong>デモとして設定したもの</strong>架空のタイ店舗154件、金額のTHB表示、期間切替・推移、細部の段階閾値、商品別ファネル補完、シミュレーション式、個別KPIの取得分類。円からの為替換算ではありません。</span></div></div><div class="drawer-callout">HTMLは表示サンプル、PDFは事業構想・基準の参照です。たとえばBPのWBはHTML比較値80%、PDFのCriterion100%を区別。全体件数は表示中のカードから算出しています。</div><p class="note">元資料自体や社内打ち合わせ記録は公開ページに添付していません。</p>`)}
const TOUR=[['月曜朝、店舗の今をつかむ。','実績・アラート・重点テーマから、今日の朝礼へ。'],['21のKPIを、改善の入口に。','実数・類似店・13週・本部を比べ、次の一手を選ぶ。'],['タイヤとバッテリー。空き作業枠。','見積提示の漏れを見つけ、現場で動かせる改善へ。'],['同じ条件の店舗から学ぶ。','154店の位置関係から、伸ばす指標と良い習慣を探す。'],['70%から、長期90%への道筋。','GS・BP・保険・用品、そして固定費改善を積み上げる。'],['気づきを、今週の行動へ。','担当と期限を揃え、朝礼で決めた一手を追跡する。']];
function openGuide(){openDrawer(`<p class="eyebrow">TMT DEALER PRESENTATION</p><h2>店舗の成長を、60秒で。</h2><p class="drawer-subtitle">タイ・トヨタ販売店のVC収益と21コアKPIを、6つの画面でつなぎます。</p><div class="guide-list">${TOUR.map((v,i)=>`<div><b>0${i+1}</b><span><strong>${v[0]}</strong>${v[1]}</span></div>`).join('')}</div><div class="drawer-callout">右上の全画面表示を使い、「プレゼンを開始」で自動再生。途中で一時停止して、KPIやシミュレーションを自由に操作できます。</div><div class="drawer-section"><h3>KEYBOARD SHORTCUTS</h3><div class="key-line"><kbd>1</kbd>〜<kbd>6</kbd> 画面切替</div><div class="key-line"><kbd>Space</kbd> 再生・一時停止</div><div class="key-line"><kbd>←</kbd><kbd>→</kbd> 前後のシーン</div><div class="key-line"><kbd>Esc</kbd> 詳細・ツアーを閉じる</div></div><button class="gold-button full-width" id="guideStart">${icon('play')} プレゼンを開始</button>`);$('#guideStart').onclick=()=>{closeDrawer();startTour()}}
function clearTourAuto(){tourAutoTimers.forEach(clearTimeout);tourAutoTimers=[]}
function startTour(){closeDrawer();state.tour=true;state.tourPaused=false;state.tourStep=0;state.tourElapsed=0;$('#tourBar').hidden=false;$('#tourPause').textContent='Ⅱ';$('#tourPause').setAttribute('aria-label','ツアーを一時停止');document.body.classList.add('touring');clearInterval(tourTimer);tourScene(0);tourTimer=setInterval(()=>{if(!state.tour||state.tourPaused||document.hidden)return;state.tourElapsed+=100;$('#tourProgress').style.width=state.tourElapsed/100+'%';if(state.tourElapsed>=10000){if(state.tourStep>=5){endTour();toast('ツアーが完了しました。各画面を自由に操作できます。')}else tourScene(state.tourStep+1)}},100)}
function tourScene(i){clearTourAuto();state.tourStep=Math.max(0,Math.min(5,i));state.tourElapsed=0;if(state.tourStep===1)Object.assign(state,{category:'ALL',status:'all',layout:'compact'});if(state.tourStep===2)state.driver='tire';if(state.tourStep===4)Object.assign(state,{tires:8.4,bay:49,cost:0,year:2026});setView(VIEWS[state.tourStep]);$('#tourStep').textContent='0'+(state.tourStep+1)+' / 06';$('#tourTitle').textContent=TOUR[state.tourStep][0];$('#tourCaption').textContent=TOUR[state.tourStep][1];$('#tourProgress').style.width='0%';$('#tourPrev').disabled=state.tourStep===0;$('#tourNext').disabled=state.tourStep===5;if(!state.tourPaused&&state.tourStep===2)tourAutoTimers.push(setTimeout(()=>{if(state.view==='drivers'&&!state.tourPaused){$('#proposalSlider').value=100;$('#proposalSlider').dispatchEvent(new Event('input'));$('#closeSlider').value=45;$('#closeSlider').dispatchEvent(new Event('input'))}},2400));if(!state.tourPaused&&state.tourStep===4)tourAutoTimers.push(setTimeout(()=>{if(state.view==='vc'&&!state.tourPaused){state.tires=15;state.bay=65;state.cost=6;$('#tireSlider').value=15;$('#baySlider').value=65;$('#costSlider').value=6;updateScenario()}},2200))}
function pauseTour(force){state.tourPaused=force??!state.tourPaused;$('#tourPause').textContent=state.tourPaused?'▷':'Ⅱ';$('#tourPause').setAttribute('aria-label',state.tourPaused?'ツアーを再生':'ツアーを一時停止');if(state.tourPaused)clearTourAuto()}
function endTour(){state.tour=false;clearInterval(tourTimer);clearTourAuto();$('#tourBar').hidden=true;document.body.classList.remove('touring')}
function bindGlobal(){document.addEventListener('click',e=>{const nav=e.target.closest('[data-view]');if(nav){if(state.tour)endTour();setView(nav.dataset.view);return}const detail=e.target.closest('[data-detail]');if(detail){openKpi(detail.dataset.detail);return}const driver=e.target.closest('[data-driver]');if(driver){if(state.tour)endTour();state.driver=driver.dataset.driver;setView('drivers');return}const group=e.target.closest('[data-open-group]');if(group){state.category=group.dataset.openGroup;state.status='all';setView('matrix');return}const dealer=e.target.closest('[data-dealer]');if(dealer){openDealer(dealer.dataset.dealer);return}if(e.target.closest('[data-funnel]')){state.driver='tire';setView('drivers');return}if(e.target.closest('[data-info="sources"]'))openSourceNotes();if(e.target.closest('[data-action="tour"]'))startTour()});$('#storeSelect').onchange=e=>{saveActions();state.store=e.target.value;state.actions=getActions();setView(state.view,{scroll:false});toast(storeInfo().name+'に切り替えました')};$('#periodSelect').onchange=e=>{state.period=e.target.value;setView(state.view,{scroll:false});toast(state.period+'週のサンプルデータに切り替えました')};$('#motionButton').onclick=toggleMotion;$('#fullscreenButton').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else toast('ブラウザの全画面表示機能をご利用ください')}catch{toast('ブラウザの全画面表示機能をご利用ください')}};document.addEventListener('fullscreenchange',()=>$('#fullscreenButton').setAttribute('aria-label',document.fullscreenElement?'全画面表示を終了':'全画面表示'));$('#guideButton').onclick=openGuide;$('#tourButton').onclick=startTour;$('#drawerClose').onclick=closeDrawer;$('#drawerBackdrop').onclick=closeDrawer;$('#tourPrev').onclick=()=>tourScene(state.tourStep-1);$('#tourNext').onclick=()=>tourScene(state.tourStep+1);$('#tourPause').onclick=()=>pauseTour();$('#tourEnd').onclick=endTour;window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(VIEWS.includes(v)){if(state.tour)endTour();setView(v)}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('#detailDrawer').hidden)closeDrawer();else if(state.tour)endTour();return}if(!$('#detailDrawer').hidden){if(e.key==='Tab'){const a=$$('button:not(:disabled),a,input,select,[tabindex="0"]',$('#detailDrawer')),first=a[0],last=a.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}return}if(/^(INPUT|SELECT|TEXTAREA)$/.test(document.activeElement?.tagName))return;if(state.tour&&[' ','ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();if(e.key===' ')pauseTour();else tourScene(state.tourStep+(e.key==='ArrowRight'?1:-1));return}if(/^[1-6]$/.test(e.key)){if(state.tour)endTour();setView(VIEWS[+e.key-1])}})}
function init(){hydrate();chartDefaults();bindGlobal();document.body.classList.toggle('motion-off',!state.motion);if(!state.motion)$('#motionButton').setAttribute('aria-label','アニメーションを再開');setView(location.hash.slice(1)||'overview');setTimeout(()=>$('#intro')?.remove(),1900);if(new URLSearchParams(location.search).get('present')==='1')setTimeout(startTour,2000)}
init();
